package vn.gomviet.security;
import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import vn.gomviet.entity.User;import javax.crypto.SecretKey;import java.nio.charset.StandardCharsets;import java.util.*;
@Service public class JwtService{private final SecretKey key;private final long accessExpiration;public JwtService(@Value("${app.jwt.secret}")String secret,@Value("${app.jwt.access-expiration-ms}")long expiration){key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));accessExpiration=expiration;}public String createAccessToken(User user){var now=new Date();return Jwts.builder().subject(user.getEmail()).claim("role",user.getRole().name()).issuedAt(now).expiration(new Date(now.getTime()+accessExpiration)).signWith(key).compact();}public String subject(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject();}public long accessExpirationSeconds(){return accessExpiration/1000;}}
